import{d as c,C as t,o as g,c as b,j as a,a as s,E as o,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第六十七章","description":"辨似不肖与大道之大，循慈、俭、不敢为天下先读三宝及其不可舍的根本。","frontmatter":{"title":"道德经第六十七章","description":"辨似不肖与大道之大，循慈、俭、不敢为天下先读三宝及其不可舍的根本。","category":"guide","aliases":["道德经第六十七章","老子第六十七章","dao de jing chapter 67"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-67.md","filePath":"daoism/dao-de-jing/chapter-67.md","lastUpdated":1794189804000}'),x={name:"daoism/dao-de-jing/chapter-67.md"},_=c({...x,setup(p){const r=[{id:"great-and-unlike",label:"天下皆谓我道大",showLabel:!0,sentences:[["天下皆谓我道大，似不",{text:"肖",glossary:"xiao"},"。夫唯大，故似不",{text:"肖",glossary:"xiao"},"。"]],note:["【白话】天下人都说我的道广大，却好像不像任何一种具体的样子。正因为它广大，所以才显得不像某一种可指认的形态。","【读法】肖取相似义。不肖承道大说不受某种局部形貌限定，不按不肖子孙的现代常用意思理解。","【读法】所据这两句未见独立逐句王注，可接下文肖则失其所以为大的注释读；大也不是形体、规模越大越好。"]},{id:"likeness-narrows",label:"若肖，久矣其细也夫",showLabel:!0,sentences:[["若",{text:"肖",glossary:"xiao"},"，久矣其",{text:"细",glossary:"xi"},"也夫！"]],note:["【白话】如果它真的只像某一种具体的形态，那它早就变得细小、局限了啊！本句从反面补明，为什么道大反而似不肖。","【王弼注择要】「久矣其细，犹曰其细久矣。」又说「肖则失其所以为大矣」，把倒装语序与局限其大的问题一并指出。","【读法】这里不是否定一切比喻和具体说明，而是提醒不能拿局部形貌把所谈的道限定尽。"]},{id:"the-three-treasures",label:"我有三宝，持而保之",showLabel:!0,sentences:[["我有",{text:"三宝",glossary:"sanbao"},"，持而保之：一曰",{text:"慈",glossary:"ci"},"，二曰",{text:"俭",glossary:"jian"},"，三曰不敢为天下先。"]],note:["【白话】我有三件珍宝，要握持并守护它们：第一是慈爱，第二是节用，第三是不敢争着做天下人的先导。","【读法】三宝在正文中明确列出，是可以持续持守的处事准则。慈并非纵容伤害，俭也不能只按少花钱理解；下文将分别说明它们的成用。","【读法】不敢为天下先先保留谦后、不抢先主导的意思，再与下文成器长相读，不能直接翻成一概不负责。"]},{id:"compassion-and-frugality",label:"慈故能勇；俭故能广",showLabel:!0,sentences:[[{text:"慈",glossary:"ci"},"故能勇；",{text:"俭",glossary:"jian"},"故能",{text:"广",glossary:"guang"},"；"]],note:["【白话】因为有慈爱，所以能够勇敢承担；因为珍惜耗费、节制用度，所以能够使所及更广。勇与广都从前面所守的根本生出。","【王弼注择要】慈下注以战守说明能勇；俭下注「节俭爱费，天下不匮，故能广也」，把广接到用度不至匮乏。","【读法】慈的勇可指为所怜惜者承担艰难，不以狠厉为唯一尺度；俭的广则来自珍惜资源，不由过度消耗换取外在扩张。"]},{id:"behind-and-capable-of-leading",label:"不敢为天下先，故能成器长",showLabel:!0,sentences:[["不敢为天下先，故能成",{text:"器长",glossary:"qizhang"},"。"]],note:["【白话】因为不敢争着走在天下人前面，所以反而能成为足以任事、为众物之长的人。谦后与成用在这里相接。","【王弼注择要】「唯后外其身，为物所归」，然后「为天下利，为物之长也」。注把后身、外身连到众物归附与有利天下。","【读法】器长的长读 zhǎng，作长者、主导者讲，不是器物的长度。这里仍有为天下之长的古代取向，后身并不取消对结果的承担。"]},{id:"taking-results-without-roots",label:"今舍慈且勇",showLabel:!0,sentences:[["今舍",{text:"慈",glossary:"ci"},{text:"且",glossary:"qie"},"勇，舍",{text:"俭",glossary:"jian"},{text:"且",glossary:"qie"},{text:"广",glossary:"guang"},"，舍后",{text:"且",glossary:"qie"},"先，死矣！"]],note:["【白话】如今若舍掉慈爱而只求勇猛，舍掉节用而只求广张，舍掉谦后而只求争先，那就走向败亡了！","【王弼注择要】「且，犹取也。」依这一训释，三个且都不是普通的而且，而是在说舍其根却强取其成效。","【读法】死矣用强烈警戒指出这种倒置的危险。不能把前文三宝变成包装勇、广、先的口号，实际仍只逐取外在结果。"]},{id:"compassion-in-conflict",label:"夫慈，以战则胜，以守则固",showLabel:!0,sentences:[["夫",{text:"慈",glossary:"ci"},"，以战则胜，以守则固。"]],note:["【白话】慈爱用于战斗，可以形成克敌的力量；用于守护，可以使防守坚固。经文以战争语境，强调慈与勇、固并不相悖。","【王弼注择要】「相慜而不避于难」，从相互悯惜而不躲避艰难说明慈如何成勇。慜为所据录文字样。","【读法】此句保留古代战守取象，不直接许诺现实军事必胜。所据注在这句话之后另作故正也，本页不擅改为故胜也后再引用。"]},{id:"heaven-and-protection",label:"天将救之，以慈卫之",showLabel:!0,sentences:[["天将救之，以",{text:"慈",glossary:"ci"},"卫之。"]],note:["【白话】天若要救助一个人，就以慈爱来护卫他。末句用天的救护来提升慈的地位，收束前面的三宝与战守。","【读法】所据末句未见单独逐句王注。这里保留古代关于天佑的表达，再从全章理解慈为所守的根，不把天救解释成现代可验证的免伤保证。"]}],n=[{id:"xiao",term:"肖",sense:1},{id:"xi",term:"细",sense:1},{id:"sanbao",term:"三宝",sense:1},{id:"ci",term:"慈",sense:1},{id:"jian",term:"俭",sense:1},{id:"guang",term:"广",sense:1},{id:"qizhang",term:"器长",sense:1},{id:"qie",term:"且",sense:1}];return(m,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第六十七章",tabindex:"-1"},[s("道德经第六十七章 "),a("a",{class:"header-anchor",href:"#道德经第六十七章","aria-label":'Permalink to "道德经第六十七章"'},"​")],-1)),o(i,{title:"慈、俭与不敢为先，怎样成为勇与广的根",summary:"本章先说大道之大不落在某一种相似的形貌里，再把持守落到三宝：慈、俭、不敢为天下先。勇、广与为长都由它们生出；若只取结果而舍其根，便转成危殆。结尾以战守与天佑的古代语言，进一步突出慈。",points:[{label:"先读",text:"不肖先作不像某种限定形态解，接着看大道之大如何落到三项持守。"},{label:"再辨",text:"慈而能勇、俭而能广、后身而能为长，重点是结果与根本相连。"},{label:"后看",text:"舍慈且勇等三句用反面警戒，再以慈贯通战守与结尾的卫护。"}],hint:"肖读 xiào，器长读 qì zhǎng，且读 qiě，依王注取求取义。不肖在本章不直接等同品行不良。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:r,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"夫唯大，故似不肖。",tone:"不落局部形貌",guide:"由下文若肖则细来读，避免把不肖误作道德贬词。"},{text:"慈故能勇；俭故能广；不敢为天下先，故能成器长。",tone:"成效与持守相连",guide:"勇、广、为长都有所依，不能只追结果而抽去根本。"},{text:"今舍慈且勇，舍俭且广，舍后且先，死矣！",tone:"反面检验三宝",guide:"且依取来读，三个舍与三个且照出本末倒置。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:n}),e[4]||(e[4]=u("",15))])}}});export{y as __pageData,_ as default};
